#rf-root,.hf-root{--x3:#574953;font-family:var(--rf-font);color:var(--rf-text)}.stage{position:absolute;inset:0;}.cam{position:absolute;inset:0;animation:st-cam 5.5s linear both;}@keyframes st-cam{from{transform:scale(1)}to{transform:scale(1.02)}}.bd{position:absolute;inset:0;overflow:hidden;background:var(--rf-bg)}.bd-grid{position:absolute;inset:0;background-image:linear-gradient(color-mix(in srgb,var(--rf-text) 6%,transparent) 2px,transparent 2px),linear-gradient(90deg,color-mix(in srgb,var(--rf-text) 6%,transparent) 2px,transparent 2px);background-size:108px 108px;background-position:-2px -2px}.tx{position:absolute;inset:0;background:var(--rf-surface);z-index:50}.tx.tx-iris-out{inset:auto;background:transparent;box-shadow:0 0 0 2400px var(--rf-surface);border-radius:50%;width:2400px;height:2400px;left:calc(50% - 1200px);top:calc(50% - 1200px);animation:tx-iris-out 0.5s cubic-bezier(.76,0,.24,1) 5s both;opacity:0}@keyframes tx-iris-out{from{opacity:1}to{opacity:1;width:0;height:0;left:50%;top:50%}}@keyframes st-rise{from{transform:translateY(120px)}to{transform:none}}
@keyframes st-pushin{from{transform:translateX(100%)}to{transform:none}}
@keyframes st-pushout{to{transform:translateX(-100%)}}
@keyframes st-zoomin{from{transform:scale(.92);opacity:0}to{transform:none;opacity:1}}
@keyframes st-zoomout{to{transform:scale(1.08);opacity:0}}
@keyframes st-fadein{from{opacity:0}to{opacity:1}}
@keyframes st-fadeout{to{opacity:0}}.rise{animation:k-rise .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-rise{from{opacity:0;transform:translateY(40px)}to{opacity:1;transform:none}}
.pop{animation:k-pop .7s cubic-bezier(.16,1,.3,1) both}@keyframes k-pop{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:none}}
.slide-l{animation:k-sl .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sl{from{opacity:0;transform:translateX(-80px)}to{opacity:1;transform:none}}
.slide-r{animation:k-sr .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sr{from{opacity:0;transform:translateX(80px)}to{opacity:1;transform:none}}
.fade{animation:k-fade .8s ease-out both}@keyframes k-fade{from{opacity:0}to{opacity:1}}.wrap{position:absolute;left:90px;right:90px;top:0;bottom:0;display:flex;flex-direction:column;justify-content:center}.mk-l{display:block}.mk-w{display:inline-block;overflow:hidden;vertical-align:top;padding:0 .02em .08em;margin-bottom:-.08em}
.mk-w>span{display:inline-block;animation:mk-up 0.9s cubic-bezier(.16,1,.3,1) both}
@keyframes mk-up{from{transform:translateY(105%)}to{transform:none}}.eb{display:inline-block;font:500 32px/1.2 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-muted)}@property --n52{syntax:'<integer>';inherits:false;initial-value:0}
.n52{counter-reset:n52 var(--n52);animation:n52-c 1.6s cubic-bezier(.16,1,.3,1) 0.7s both}
.n52::after{content:counter(n52,decimal)}
@keyframes n52-c{from{--n52:0}to{--n52:9}}@property --n53{syntax:'<integer>';inherits:false;initial-value:0}
.n53{counter-reset:n53 var(--n53);animation:n53-c 1.6s cubic-bezier(.16,1,.3,1) 0.88s both}
.n53::after{content:counter(n53,decimal)}
@keyframes n53-c{from{--n53:0}to{--n53:7}}@property --n54{syntax:'<integer>';inherits:false;initial-value:0}
.n54{counter-reset:n54 var(--n54);animation:n54-c 1.6s cubic-bezier(.16,1,.3,1) 1.06s both}
.n54::after{content:counter(n54,decimal)}
@keyframes n54-c{from{--n54:0}to{--n54:5}}@property --n55{syntax:'<integer>';inherits:false;initial-value:0}
.n55{counter-reset:n55 var(--n55);animation:n55-c 1.6s cubic-bezier(.16,1,.3,1) 1.24s both}
.n55::after{content:counter(n55,decimal)}
@keyframes n55-c{from{--n55:0}to{--n55:2}}.wrap>div:first-child{margin-bottom:40px}
