.val{position:absolute;right:28px;top:0;bottom:0;display:flex;align-items:center;font:500 46px/1 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-text)}
.src{margin-top:30px;font:500 28px/1.3 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-muted);opacity:.8}

